    inline float predictYellow(std::array<float, kNumFeatures> features) {
        float score = kBaseline;

        std::size_t idx = 0;

        while (idx < kModel.size()) {
            const Node& node = kModel[idx];
            if (node.feature < 0) {
                score += node.value;
                idx = node.left;
            } else {
                if (features[node.feature] <= node.value) {
                    idx = node.left;
                } else {
                    idx = node.right;
                }
            }
        }

        return 1 / (1 + std::exp(-score));
    }

